// TH18 v1.00a st02bs::BossCard2/source540-695. Source t0=card124.
const TIME_LIMIT: int = 2522;
const SOURCE_LIMIT: int = 2400;

xformdef LEAF_MOTION(duration: int, omega: angle) {
    // Native300: ANGLE_ACCEL-end and ACCEL-end each rerun OFFSCREEN once before its expiry.
    // d<=219 and d+20<=239, so both extra passes precede clearing: same expiry as 298 updates.
    offscreen_keep(298);
    set_ang_vel(omega);
    set_accel(0.003fx);
    wait(duration);
    // Source ANGLE_ACCEL ends; ACCEL captures this angle once for its fixed vector.
    set_ang_vel(0bam);
    set_accel(0fx);
    @20 set_gravity(at_effect(-0.04fx*cos($self_angle)), at_effect(-0.04fx*sin($self_angle)));
    set_gravity(0fx, 0fx);
}
xformdef BIG_MOTION {
    // Single VELTIME, current-angle direction, no later logical-speed readers.
    @60 set_accel((0.8fx-3fx)/60);
    set_accel(0fx);
}
sub configure() {
    for id in 0..2 {
        sh_reset(id);
        sh_sprite(id, TH18_DROPLET, 10);
        sh_aim(id, 0);
        sh_ring(id, 1);
        sh_count(id, 16, 1);
        sh_angle(id, -90deg, 20deg);
        sh_speed(id, 1.5fx, 0fx);
        sh_dist(id, 26fx); // dist32 minus ANIM a1 retreat4*1.5.
        sh_offset(id, 0fx, -16fx);
    }
}
sub emit_pair(b: angle) {
    // Source616/617 and642/643 both write id0. The second write wins; id1 remains -90deg.
    sh_angle(0, -b, 20deg);
    var d0: int = 180+rand(65536)%40;
    var d1: int = 180+rand(65536)%40;
    sh_xform(0, LEAF_MOTION(d0, 164bam));
    sh_xform(1, LEAF_MOTION(d1, -164bam));
    sh_fire(0);
    sh_fire(1);
}
sub attack() {
    configure();
    var b: angle = (rand(65536)-32768) as angle;
    var count: int = 7;
    var interval: int = 15;
    var rank: int = global(GVAR_RANK);
    if rank == 0 { count = 3; }
    if rank == 2 { interval = 10; }
    if rank == 3 { interval = 8; }
    for j in 0..count {
        if $frame >= self_int(1) { return; }
        emit_pair(b);
        b = b+910bam; // .087266rad nearest BAM.
        card_wait(interval);
    }
    if rank >= 2 {
        sh_sprite(0, TH18_TALISMAN, 10); // Source638 only changes id0, id1 keeps droplet.
        var extra: int = 5;
        if rank == 3 { extra = 9; }
        for k in 0..extra {
            if $frame >= self_int(1) { return; }
            emit_pair(b);
            b = b+910bam;
            card_wait(interval);
        }
    }
}
async sub proximity() {
    sh_reset(2);
    sh_sprite(2, TH18_BIG_BALL2, 3);
    sh_aim(2, 1);
    sh_ring(2, 1);
    sh_count(2, 10, 1);
    sh_speed(2, 3fx, 0fx);
    sh_angle(2, 0deg, 30deg);
    sh_dist(2, -12fx); // ANIM a1 retreat4*3. Source has no etDist.
    sh_xform(2, BIG_MOTION);
    for j in 0..5000 {
        wait(30);
        if $frame >= self_int(1) { return; }
        if dist($player_x-$self_x, $player_y-$self_y) <= 200fx {
            sh_fire(2);
        }
    }
}
async sub pattern() {
    wait(120);
    set_self_int(2, $frame);
    set_self_int(1, $frame+SOURCE_LIMIT);
    set_self_int(0, 60);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(90);
    // Source584/585 floatTime A is dead: no subsequent read in this attack.
    spawn proximity();
    loop {
        if $frame >= self_int(1) { return; }
        attack();
        card_wait(130);
        if $frame >= self_int(1) { return; }
        card_move_rand();
        card_wait(60);
    }
}
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    spell_begin(0, 12, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 128fx, 2300, 0, 0, 0, boss_main);
    loop { wait(600); }
}

// TH18 v1.00a BossCard2 only. int0=next-step, int1=source end, int2=source start; fx0/1=logical unit vector.
// All source wait(n) inside this attack must use card_wait(n), in the same owner task.
// No new task: emit uses the current position, phase5 then performs the next source movement tick.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 1.7fx*((60-k) as fx)/60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 104fx { ny = 104fx; }
    if ny > 152fx { ny = 152fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 405b90 = signed unit random * pi. Values below are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -60fx {
        a = r/3;
    } else if $self_x > 60fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source explicitly normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately do not normalize this branch before the source fabs tests.
    }
    if $self_y < 116fx {
        if a < 0 { a = -a; }
    } else if $self_y > 140fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon0.05rad. Nearest BAM boundaries (normal angle quantization).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        if $frame >= self_int(1) { move_vel(0, 0deg, 0fx, EASE_LINEAR); return; }
        card_arm_next_step();
    }
}

